package org.retrobridge.gmail2012.provider;
import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.util.Base64;import org.json.*;import java.io.*;import java.util.*;import java.lang.reflect.*;
public final class PixelAttachments {
 static final Set<String> BUSY=Collections.synchronizedSet(new HashSet<String>());
 static ArrayList<Gmail.Attachment> model(Context c,String message,JSONArray files)throws Exception {
  ArrayList<Gmail.Attachment> result=new ArrayList<Gmail.Attachment>();if(files==null)return result;SharedPreferences.Editor prefs=c.getSharedPreferences("pixel-attachments",0).edit();
  for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String part=f.getString("part");if(!part.matches("[0-9.]{1,80}"))continue;Gmail.Attachment a=new Gmail.Attachment();a.partId=part;a.name=f.getString("name");a.contentType=a.simpleContentType=f.getString("mime");a.size=f.getInt("size");a.origin=Gmail.AttachmentOrigin.SERVER_ATTACHMENT;a.originExtras="pixel";prefs.putString(message+":"+part,f.getString("id"));result.add(a);}prefs.commit();return result;
 }
 public static Cursor query(final Object manager,final long conversation,final long message,final Gmail.Attachment a,final Gmail.AttachmentRendition rendition,final boolean save,String[] projection){
  try{
   final Context c=(Context)PixelMail.field(manager,"mContext");final SQLiteDatabase db=(SQLiteDatabase)PixelMail.field(manager,"mDb");final String account=(String)PixelMail.field(manager,"mAccount");final String where="messages_messageId=? AND messages_partId=? AND desiredRendition=? AND saveToSd=?";final String[] args={Long.toString(message),a.partId,rendition.toString(),save?"1":"0"};
   String key=account+":"+message+":"+a.partId+":"+save+":"+rendition;Cursor old=db.query("attachments",new String[]{"status","filename"},where,args,null,null,null);boolean ready=false;try{if(old.moveToFirst())ready=old.getInt(0)==200&&old.getString(1)!=null&&new File(Uri.parse(old.getString(1)).getPath()).isFile();}finally{old.close();}
   if(!ready&&BUSY.add(key)){
    ContentValues v=new ContentValues();v.put("messages_conversation",conversation);v.put("messages_messageId",message);v.put("messages_partId",a.partId);v.put("originExtras",a.originExtras);v.put("desiredRendition",rendition.toString());v.put("downloadedRendition",rendition.toString());v.put("saveToSd",save?1:0);v.put("downloadId",-1);v.put("status",192);v.put("filename",a.name);v.put("mimeType",a.contentType);if(db.update("attachments",v,where,args)==0)db.insertOrThrow("attachments",null,v);
    final String jobKey=key;new Thread(new Runnable(){public void run(){try{
     File root=save?new File(android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_DOWNLOADS),"Gmail"):new File(c.getCacheDir(),"attachments");root.mkdirs();String name=a.name.replaceAll("[^A-Za-z0-9._ -]","_");if(name.length()>120)name=name.substring(name.length()-120);if(name.isEmpty())name="attachment";File file=new File(root,Long.toHexString(message)+"-"+a.partId+"-"+name),temp=new File(root,file.getName()+".part");
     String attachment=c.getSharedPreferences("pixel-attachments",0).getString(Long.toHexString(message)+":"+a.partId,"");if(attachment.isEmpty())throw new IOException("Attachment information unavailable");int offset=0,total=-1;
     try{FileOutputStream out=new FileOutputStream(temp);try{do{JSONObject r=PixelMail.call(new JSONObject().put("op","attachment").put("account",account).put("message",Long.toHexString(message)).put("attachment",attachment).put("offset",offset));if(r.getInt("offset")!=offset)throw new IOException("Attachment offset mismatch");if(total<0)total=r.getInt("total");if(total!=r.getInt("total")||total<0||total>6000000)throw new IOException("Attachment size invalid");byte[] data=Base64.decode(r.getString("data"),Base64.URL_SAFE|Base64.NO_WRAP);if(data.length==0&&offset<total||offset+data.length>total)throw new IOException("Attachment transfer incomplete");out.write(data);offset+=data.length;}while(offset<total);out.getFD().sync();}finally{out.close();}if(!temp.renameTo(file))throw new IOException("Cannot save attachment");}finally{if(temp.exists())temp.delete();}
     ContentValues done=new ContentValues();done.put("status",200);done.put("filename",Uri.fromFile(file).toString());db.update("attachments",done,where,args);
    }catch(Exception ex){ContentValues fail=new ContentValues();fail.put("status",500);db.update("attachments",fail,where,args);android.util.Log.w("PixelGmail",PixelMail.safeError(ex));}finally{BUSY.remove(jobKey);try{Method notify=manager.getClass().getDeclaredMethod("notifyChanged",long.class);notify.setAccessible(true);notify.invoke(manager,conversation);}catch(Exception ignored){}}}},"Gmail attachment").start();
   }
   Method query=manager.getClass().getDeclaredMethod("newAttachmentCursor",long.class,String.class,Gmail.AttachmentRendition.class,boolean.class,String[].class);query.setAccessible(true);return (Cursor)query.invoke(manager,message,a.partId,rendition,save,projection);
  }catch(Exception e){throw new IllegalStateException("Attachment query failed",e);}
 }
}
